-- Correct the three text fields that were originally imported with a console
-- code page instead of UTF-8, then add a display-only option to each book.
-- Hex UTF-8 literals keep this migration independent of the mysql client's
-- active code page.

START TRANSACTION;

UPDATE `skill_template`
SET
    `NAME` = CONVERT(0x4B68C3AD204E677579C3AA6E205472E1BAA36D USING utf8mb4),
    `dam_info` = CONVERT(0x53C3A174207468C6B0C6A16E673A202325202D20787579C3AA6E2074E1BB916920C491612033206DE1BBA563207469C3AA75 USING utf8mb4),
    `skills` = CONVERT( USING utf8mb4)
WHERE `nclass_id` = 0 AND `id` = 27;

INSERT INTO `item_option_template` (`id`, `NAME`)
VALUES (252, CONVERT(0x4B68C3AD204E677579C3AA6E205472E1BAA36D2063E1BAA5702023 USING utf8mb4))
ON DUPLICATE KEY UPDATE `NAME` = VALUES(`NAME`);

DELETE `item_shop_option`
FROM `item_shop_option`
INNER JOIN `item_shop` ON `item_shop`.`id` = `item_shop_option`.`item_shop_id`
WHERE `item_shop`.`tab_id` = 11
  AND `item_shop`.`temp_id` BETWEEN 2219 AND 2225
  AND `item_shop_option`.`option_id` = 252;

INSERT INTO `item_shop_option` (`item_shop_id`, `option_id`, `param`)
SELECT `id`, 252, `temp_id` - 2218
FROM `item_shop`
WHERE `tab_id` = 11 AND `temp_id` BETWEEN 2219 AND 2225;

COMMIT;
